def solve_math_problem(base: int, exp1: int, exp2: int, mod: int) -> int:
    """
    Calculates (base^(exp1^exp2)) % mod using Euler's totient theorem.
    """
    def get_phi(n: int) -> int:
        result = n
        p = 2
        while p * p <= n:
            if n % p == 0:
                while n % p == 0:
                    n //= p
                result -= result // p
            p += 1
        if n > 1:
            result -= result // n
        return result

    phi = get_phi(mod)

    # Using Euler's totient theorem: a^b % n = a^(b % phi(n) + phi(n)) % n
    # This holds if b >= phi(n).
    exponent = pow(exp1, exp2, phi) + phi
    return pow(base, exponent, mod)
