from typing import Tuple, Dict

def solve_math_problem(roots: Tuple[int, ...], power: int, target_sum_limit: int) -> int:
    """
    Calculates the sum of coefficients a_k for even k in the polynomial
    product_{r in roots} (x + r)^power.
    """
    # Polynomial represented as a dictionary {exponent: coefficient}
    # Start with the polynomial 1 (x^0)
    poly: Dict[int, int] = {0: 1}

    for r in roots:
        # Multiply current poly by (x + r)^power
        # (x + r)^power = sum_{i=0}^power C(power, i) * x^i * r^(power-i)
        factor_poly: Dict[int, int] = {}
        for i in range(power + 1):
            # Binomial coefficient C(power, i)
            comb = 1
            for j in range(i):
                comb = comb * (power - j) // (j + 1)

            coeff = comb * (r ** (power - i))
            factor_poly[i] = coeff

        new_poly: Dict[int, int] = {}
        for exp1, coeff1 in poly.items():
            for exp2, coeff2 in factor_poly.items():
                new_exp = exp1 + exp2
                new_poly[new_exp] = new_poly.get(new_exp, 0) + (coeff1 * coeff2)
        poly = new_poly

    total_sum = 0
    for k in range(2, target_sum_limit + 1, 2):
        total_sum += poly.get(k, 0)

    return total_sum
